     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Tetris</title>
     7	<style>
     8	  :root {
     9	    --cell: 28px;
    10	    --bg: #14161c;
    11	    --panel: #1d2029;
    12	    --grid: #262a35;
    13	    --text: #e8eaf0;
    14	    --muted: #8a90a0;
    15	  }
    16	  * { box-sizing: border-box; }
    17	  body {
    18	    margin: 0;
    19	    min-height: 100vh;
    20	    display: flex;
    21	    align-items: center;
    22	    justify-content: center;
    23	    background: var(--bg);
    24	    color: var(--text);
    25	    font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    26	  }
    27	  .game {
    28	    display: flex;
    29	    gap: 20px;
    30	    align-items: flex-start;
    31	    padding: 16px;
    32	  }
    33	  .board {
    34	    display: grid;
    35	    grid-template-columns: repeat(10, var(--cell));
    36	    grid-template-rows: repeat(20, var(--cell));
    37	    gap: 1px;
    38	    padding: 1px;
    39	    background: var(--grid);
    40	    border: 2px solid #3a3f4d;
    41	    border-radius: 4px;
    42	    position: relative;
    43	  }
    44	  .cell { background: var(--bg); }
    45	  .side {
    46	    display: flex;
    47	    flex-direction: column;
    48	    gap: 12px;
    49	    min-width: 140px;
    50	  }
    51	  .box {
    52	    background: var(--panel);
    53	    border-radius: 6px;
    54	    padding: 10px 12px;
    55	  }
    56	  .label {
    57	    font-size: 11px;
    58	    text-transform: uppercase;
    59	    letter-spacing: 0.08em;
    60	    color: var(--muted);
    61	  }
    62	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
    63	  .preview {
    64	    display: flex;
    65	    flex-direction: column;
    66	    gap: 10px;
    67	    margin-top: 8px;
    68	  }
    69	  .preview-item {
    70	    display: grid;
    71	    grid-template-columns: repeat(4, 16px);
    72	    grid-template-rows: repeat(2, 16px);
    73	    gap: 1px;
    74	  }
    75	  .hold-used .preview-item { opacity: 0.35; }
    76	  .help { color: var(--muted); font-size: 12px; }
    77	  .help kbd {
    78	    background: #2b2f3a;
    79	    border-radius: 3px;
    80	    padding: 0 4px;
    81	    font: inherit;
    82	    color: var(--text);
    83	  }
    84	  .overlay {
    85	    position: absolute;
    86	    inset: 0;
    87	    display: flex;
    88	    flex-direction: column;
    89	    align-items: center;
    90	    justify-content: center;
    91	    gap: 10px;
    92	    background: rgba(10, 11, 15, 0.78);
    93	    font-size: 20px;
    94	    font-weight: 600;
    95	  }
    96	  .overlay button {
    97	    font: inherit;
    98	    font-size: 14px;
    99	    padding: 6px 14px;
   100	    border: 0;
   101	    border-radius: 4px;
   102	    background: #4a8cff;
   103	    color: #fff;
   104	    cursor: pointer;
   105	  }
   106	  .overlay[hidden] { display: none; }
   107	
   108	  /* Piece colours */
   109	  .p-I { background: #30c7e6; }
   110	  .p-O { background: #f2d33a; }
   111	  .p-T { background: #a35ee0; }
   112	  .p-S { background: #4ccf5a; }
   113	  .p-Z { background: #e8474a; }
   114	  .p-J { background: #3b6ee8; }
   115	  .p-L { background: #f09a2e; }
   116	</style>
   117	</head>
   118	<body>
   119	<div class="game">
   120	  <div class="board" data-testid="board" id="board">
   121	    <div class="overlay" data-testid="game-over" id="overlay" hidden>
   122	      <div>Game over</div>
   123	      <button type="button" id="restart">Play again</button>
   124	    </div>
   125	  </div>
   126	  <div class="side">
   127	    <div class="box">
   128	      <div class="label">Score</div>
   129	      <div class="value" data-testid="score" id="score">0</div>
   130	    </div>
   131	    <div class="box">
   132	      <div class="label">Level</div>
   133	      <div class="value" data-testid="level" id="level">1</div>
   134	    </div>
   135	    <div class="box">
   136	      <div class="label">Lines</div>
   137	      <div class="value" data-testid="lines" id="lines">0</div>
   138	    </div>
   139	    <div class="box" id="hold-box">
   140	      <div class="label">Hold</div>
   141	      <div class="preview">
   142	        <div class="preview-item" data-testid="hold-piece" id="hold" data-piece=""></div>
   143	      </div>
   144	    </div>
   145	    <div class="box">
   146	      <div class="label">Next</div>
   147	      <div class="preview" data-testid="next-piece" id="preview"></div>
   148	    </div>
   149	    <div class="box help">
   150	      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>
   151	      <div><kbd>↑</kbd> <kbd>X</kbd> Rotate</div>
   152	      <div><kbd>↓</kbd> Soft drop</div>
   153	      <div><kbd>Space</kbd> Hard drop</div>
   154	      <div><kbd>C</kbd> <kbd>Shift</kbd> Hold</div>
   155	    </div>
   156	  </div>
   157	</div>
   158	
   159	<script>
   160	(function () {
   161	  "use strict";
   162	
   163	  var ROWS = 20;
   164	  var COLS = 10;
   165	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
   166	
   167	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
   168	  var SHAPES = {
   169	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
   170	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
   171	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
   172	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
   173	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
   174	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
   175	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
   176	  };
   177	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
   178	
   179	  // The I piece has its own rotation states so it turns in place like the
   180	  // guideline piece, without ever reaching above the piece's own row.
   181	  var I_STATES = [
   182	    [[0, 0], [0, 1], [0, 2], [0, 3]],
   183	    [[0, 2], [1, 2], [2, 2], [3, 2]],
   184	    [[1, 0], [1, 1], [1, 2], [1, 3]],
   185	    [[0, 1], [1, 1], [2, 1], [3, 1]]
   186	  ];
   187	  // Sideways shifts tried, in order, when a rotated shape does not fit.
   188	  var KICKS = [0, -1, 1, -2, 2];
   189	
   190	  // Locking rule.
   191	  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
   192	  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
   193	
   194	  // Scoring rule. Points for a clear depend on how many rows go at once, times
   195	  // the current level. The table grows faster than the row count, so clearing
   196	  // rows together always beats clearing the same rows one at a time.
   197	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
   198	  var SOFT_DROP_POINTS = 1; // per cell moved down by the player
   199	  var HARD_DROP_POINTS = 2; // per cell dropped
   200	
   201	  // Levelling rule. One level per LINES_PER_LEVEL lines cleared, never down.
   202	  var LINES_PER_LEVEL = 10;
   203	
   204	  // ---- State ----
   205	  var board;       // ROWS x COLS array of piece letters or null
   206	  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
   207	  var queue;       // upcoming piece letters, soonest first
   208	  var bag;         // 7-bag for the random generator
   209	  var hold;        // letter of the held piece, or null
   210	  var canHold;     // false once the falling piece has used its hold
   211	  var score, level, lines, status;
   212	  var timer = null;
   213	
   214	  function emptyBoard() {
   215	    var b = [];
   216	    for (var r = 0; r < ROWS; r++) {
   217	      var row = [];
   218	      for (var c = 0; c < COLS; c++) row.push(null);
   219	      b.push(row);
   220	    }
   221	    return b;
   222	  }
   223	
   224	  function randomPiece() {
   225	    if (!bag || bag.length === 0) {
   226	      bag = TYPES.slice();
   227	      for (var i = bag.length - 1; i > 0; i--) {
   228	        var j = Math.floor(Math.random() * (i + 1));
   229	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
   230	      }
   231	    }
   232	    return bag.pop();
   233	  }
   234	
   235	  function sanitizeQueue(q) {
   236	    if (!Array.isArray(q)) return [];
   237	    return q.map(function (x) { return String(x).toUpperCase(); })
   238	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
   239	  }
   240	
   241	  // Keep at least the next piece queued for the preview.
   242	  var PREVIEW_COUNT = 1;
   243	  function fillQueue() {
   244	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
   245	  }
   246	
   247	  function pieceCells(p, dRow, dCol) {
   248	    var out = [];
   249	    for (var i = 0; i < p.shape.length; i++) {
   250	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
   251	    }
   252	    return out;
   253	  }
   254	
   255	  function fits(p, dRow, dCol) {
   256	    var cells = pieceCells(p, dRow, dCol);
   257	    for (var i = 0; i < cells.length; i++) {
   258	      var r = cells[i][0], c = cells[i][1];
   259	      if (c < 0 || c >= COLS || r >= ROWS) return false;
   260	      if (r >= 0 && board[r][c]) return false;
   261	    }
   262	    return true;
   263	  }
   264	
   265	  function spawn() {
   266	    fillQueue();
   267	    var type = queue.shift();
   268	    fillQueue();
   269	    enter(type);
   270	  }
   271	
   272	  // Put a piece of the given type at the spawn position, or end the game if
   273	  // it does not fit there.
   274	  function enter(type) {
   275	    var p = {
   276	      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
   277	      lockTicks: 0, lockResets: 0
   278	    };
   279	    if (!fits(p, 0, 0)) {
   280	      current = null;
   281	      status = "gameover";
   282	      stopTimer();
   283	      return;
   284	    }
   285	    current = p;
   286	  }
   287	
   288	  function lock() {
   289	    var cells = pieceCells(current, 0, 0);
   290	    for (var i = 0; i < cells.length; i++) {
   291	      var r = cells[i][0], c = cells[i][1];
   292	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
   293	    }
   294	    current = null;
   295	    canHold = true;
   296	    clearLines();
   297	    spawn();
   298	  }
   299	
   300	  // Remove every full row; everything above drops down to fill the gap.
   301	  function clearLines() {
   302	    var kept = board.filter(function (row) {
   303	      return row.some(function (v) { return !v; });
   304	    });
   305	    var cleared = ROWS - kept.length;
   306	    if (cleared === 0) return;
   307	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
   308	    board = kept;
   309	    score += CLEAR_POINTS[cleared] * level;
   310	    // Each multiple of LINES_PER_LEVEL crossed adds one level, counting on
   311	    // from whatever the level is now (setLevel may have moved it).
   312	    var gained = Math.floor((lines + cleared) / LINES_PER_LEVEL) - Math.floor(lines / LINES_PER_LEVEL);
   313	    lines += cleared;
   314	    if (gained > 0) {
   315	      level += gained;
   316	      if (timer !== null) startTimer();
   317	    }
   318	  }
   319	
   320	  // One gravity step. The real timer, tick() and a falling soft drop run this.
   321	  // If the piece cannot fall, the step counts one tick of lock delay instead.
   322	  // Returns true if the piece moved down.
   323	  function gravityStep() {
   324	    if (status !== "running" || !current) return false;
   325	    if (fits(current, 1, 0)) {
   326	      current.row += 1;
   327	      current.lockTicks = 0;
   328	      return true;
   329	    }
   330	    current.lockTicks += 1;
   331	    if (current.lockTicks >= LOCK_DELAY) lock();
   332	    return false;
   333	  }
   334	
   335	  // Player input on a resting piece restarts the lock delay, up to
   336	  // MAX_LOCK_RESETS times per piece.
   337	  function restartLockDelay() {
   338	    if (current.lockResets < MAX_LOCK_RESETS) {
   339	      current.lockResets += 1;
   340	      current.lockTicks = 0;
   341	    }
   342	  }
   343	
   344	  // On a resting piece, soft drop acts like a sideways move: it restarts the
   345	  // lock delay and never counts toward locking. It scores nothing there,
   346	  // because the piece does not move.
   347	  function softDrop() {
   348	    if (status !== "running" || !current) return;
   349	    if (!fits(current, 1, 0)) {
   350	      restartLockDelay();
   351	      return;
   352	    }
   353	    if (gravityStep()) score += SOFT_DROP_POINTS;
   354	  }
   355	
   356	  function move(dCol) {
   357	    if (status !== "running" || !current) return;
   358	    if (!fits(current, 0, dCol)) return;
   359	    var resting = !fits(current, 1, 0);
   360	    current.col += dCol;
   361	    if (resting) restartLockDelay();
   362	  }
   363	
   364	  function rotatedShape(p) {
   365	    var rot = (p.rot + 1) % 4;
   366	    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
   367	    var size = p.type === "O" ? 2 : 3;
   368	    return {
   369	      rot: rot,
   370	      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
   371	    };
   372	  }
   373	
   374	  // Rotate clockwise. If the turned shape does not fit, try shifting it
   375	  // sideways; if nothing fits, leave the piece exactly as it was.
   376	  function rotateCW() {
   377	    if (status !== "running" || !current) return;
   378	    var next = rotatedShape(current);
   379	    var trial = { row: current.row, col: current.col, shape: next.shape };
   380	    for (var i = 0; i < KICKS.length; i++) {
   381	      if (fits(trial, 0, KICKS[i])) {
   382	        current.col += KICKS[i];
   383	        current.rot = next.rot;
   384	        current.shape = next.shape;
   385	        return;
   386	      }
   387	    }
   388	  }
   389	
   390	  function hardDrop() {
   391	    if (status !== "running" || !current) return;
   392	    while (fits(current, 1, 0)) {
   393	      current.row += 1;
   394	      score += HARD_DROP_POINTS;
   395	    }
   396	    lock();
   397	  }
   398	
   399	  // Set the falling piece aside. An empty slot takes it and the next piece
   400	  // comes in; a full slot swaps with it. One hold per piece until it locks.
   401	  function holdPiece() {
   402	    if (status !== "running" || !current || !canHold) return;
   403	    var type = current.type;
   404	    current = null;
   405	    canHold = false;
   406	    if (hold === null) {
   407	      hold = type;
   408	      spawn();
   409	    } else {
   410	      var out = hold;
   411	      hold = type;
   412	      enter(out);
   413	    }
   414	  }
   415	
   416	  var ACTIONS = {
   417	    left: function () { move(-1); },
   418	    right: function () { move(1); },
   419	    rotateCW: rotateCW,
   420	    softDrop: softDrop,
   421	    hardDrop: hardDrop,
   422	    hold: holdPiece
   423	  };
   424	
   425	  // ---- Timer ----
   426	  function gravityInterval() {
   427	    return Math.max(100, 1000 - (level - 1) * 100);
   428	  }
   429	
   430	  function onTimer() {
   431	    gravityStep();
   432	    render();
   433	  }
   434	
   435	  function startTimer() {
   436	    stopTimer();
   437	    timer = setInterval(onTimer, gravityInterval());
   438	  }
   439	
   440	  function stopTimer() {
   441	    if (timer !== null) {
   442	      clearInterval(timer);
   443	      timer = null;
   444	    }
   445	  }
   446	
   447	  // ---- Rendering (synchronous) ----
   448	  var boardEl = document.getElementById("board");
   449	  var overlayEl = document.getElementById("overlay");
   450	  var scoreEl = document.getElementById("score");
   451	  var levelEl = document.getElementById("level");
   452	  var linesEl = document.getElementById("lines");
   453	  var previewEl = document.getElementById("preview");
   454	  var holdEl = document.getElementById("hold");
   455	  var holdBoxEl = document.getElementById("hold-box");
   456	  var holdMinis = [];
   457	  var cellEls = [];
   458	  var previewItems = []; // [{ el, cells }] one per upcoming piece
   459	
   460	  (function buildDom() {
   461	    for (var r = 0; r < ROWS; r++) {
   462	      var row = [];
   463	      for (var c = 0; c < COLS; c++) {
   464	        var el = document.createElement("div");
   465	        el.className = "cell";
   466	        el.setAttribute("data-testid", "cell");
   467	        el.setAttribute("data-row", String(r));
   468	        el.setAttribute("data-col", String(c));
   469	        el.setAttribute("data-filled", "false");
   470	        el.setAttribute("data-piece", "");
   471	        boardEl.insertBefore(el, overlayEl);
   472	        row.push(el);
   473	      }
   474	      cellEls.push(row);
   475	    }
   476	    for (var i = 0; i < PREVIEW_COUNT; i++) {
   477	      var item = document.createElement("div");
   478	      item.className = "preview-item";
   479	      item.setAttribute("data-testid", "next-piece-item");
   480	      item.setAttribute("data-piece", "");
   481	      previewEl.appendChild(item);
   482	      previewItems.push({ el: item, cells: buildMinis(item) });
   483	    }
   484	    holdMinis = buildMinis(holdEl);
   485	  })();
   486	
   487	  function buildMinis(parent) {
   488	    var minis = [];
   489	    for (var k = 0; k < 8; k++) {
   490	      var m = document.createElement("div");
   491	      m.className = "mini";
   492	      parent.appendChild(m);
   493	      minis.push(m);
   494	    }
   495	    return minis;
   496	  }
   497	
   498	  function drawMini(minis, type) {
   499	    for (var k = 0; k < minis.length; k++) minis[k].className = "mini";
   500	    if (!type) return;
   501	    SHAPES[type].forEach(function (off) {
   502	      minis[off[0] * 4 + off[1]].className = "mini p-" + type;
   503	    });
   504	  }
   505	
   506	  function setCell(el, type) {
   507	    var piece = type || "";
   508	    if (el.getAttribute("data-piece") === piece) return;
   509	    el.className = piece ? "cell p-" + piece : "cell";
   510	    el.setAttribute("data-filled", piece ? "true" : "false");
   511	    el.setAttribute("data-piece", piece);
   512	  }
   513	
   514	  function render() {
   515	    var view = board.map(function (row) { return row.slice(); });
   516	    if (current) {
   517	      var cells = pieceCells(current, 0, 0);
   518	      for (var i = 0; i < cells.length; i++) {
   519	        var r = cells[i][0], c = cells[i][1];
   520	        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) view[r][c] = current.type;
   521	      }
   522	    }
   523	    for (var rr = 0; rr < ROWS; rr++) {
   524	      for (var cc = 0; cc < COLS; cc++) setCell(cellEls[rr][cc], view[rr][cc]);
   525	    }
   526	
   527	    scoreEl.textContent = String(score);
   528	    levelEl.textContent = String(level);
   529	    linesEl.textContent = String(lines);
   530	
   531	    previewItems.forEach(function (item, idx) {
   532	      var type = queue[idx] || "";
   533	      item.el.setAttribute("data-piece", type);
   534	      item.el.hidden = !type;
   535	      drawMini(item.cells, type);
   536	    });
   537	
   538	    holdEl.setAttribute("data-piece", hold || "");
   539	    drawMini(holdMinis, hold);
   540	    holdBoxEl.classList.toggle("hold-used", !canHold);
   541	
   542	    overlayEl.hidden = status !== "gameover";
   543	  }
   544	
   545	  // ---- Game control ----
   546	  function newGame(q) {
   547	    board = emptyBoard();
   548	    bag = [];
   549	    queue = sanitizeQueue(q);
   550	    score = 0;
   551	    level = 1;
   552	    lines = 0;
   553	    hold = null;
   554	    canHold = true;
   555	    status = "running";
   556	    current = null;
   557	    spawn();
   558	    if (status === "running") startTimer();
   559	    render();
   560	  }
   561	
   562	  function parseRows(rows) {
   563	    var b = emptyBoard();
   564	    if (!Array.isArray(rows)) return b;
   565	    for (var r = 0; r < ROWS && r < rows.length; r++) {
   566	      var line = String(rows[r]);
   567	      for (var c = 0; c < COLS && c < line.length; c++) {
   568	        var ch = line.charAt(c).toUpperCase();
   569	        b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
   570	      }
   571	    }
   572	    return b;
   573	  }
   574	
   575	  function boardToRows() {
   576	    return board.map(function (row) {
